// n8n Code node: "Test Emails" — outputs 10 items, one per test email.
// The LLM chain then runs once per item.
const tests = [
  {
    "id": "T01",
    "category": "baseline — clean single item",
    "email": "Hi,\n\nWe'd like a quote for 20 pcs of P. OMG, medium size.\nShipping to Miami, FL.\n\nThanks,\nRyan",
    "expected": {
      "route": "auto_quote",
      "品項": [
        {
          "名稱": "OMG",
          "尺寸": "M",
          "數量": 20
        }
      ],
      "total_units": 20,
      "discount": 0,
      "unit_prices": {
        "OMG M": 42.0
      },
      "總計_USD": 840.0,
      "note": "Control case."
    }
  },
  {
    "id": "T02",
    "category": "multiple items + tier discount across items",
    "email": "Hello FernzLand team,\n\nFor our spring restock we're looking at:\n- Jenny #2, small x 10\n- Nano, medium x 15\n- Ginka, medium x 10\n\nCan you send a combined quote?\n\nBest regards,\nSanne de Vries\nGreenhouse Utrecht",
    "expected": {
      "route": "auto_quote",
      "品項": [
        {
          "名稱": "Jenny #2",
          "尺寸": "S",
          "數量": 10
        },
        {
          "名稱": "Nano",
          "尺寸": "M",
          "數量": 15
        },
        {
          "名稱": "Ginka",
          "尺寸": "M",
          "數量": 10
        }
      ],
      "total_units": 35,
      "discount": 0.15,
      "unit_prices": {
        "Jenny #2 S": 25.5,
        "Nano M": 35.7,
        "Ginka M": 25.5
      },
      "總計_USD": 1045.5,
      "note": "No single line exceeds 20, but the TOTAL is 35 -> 15% off on every line. Per-line tiering would give 1230.00 = FAIL."
    }
  },
  {
    "id": "T03",
    "category": "missing quantity",
    "email": "Hi there,\n\nSaw your post about Pearl Queen on Instagram. What's your wholesale price? Do you have them in stock right now?\n\nCheers,\nMark",
    "expected": {
      "route": "human_review",
      "reason": "quantity missing",
      "品項": [
        {
          "名稱": "Pearl Queen",
          "尺寸": null,
          "數量": null
        }
      ],
      "note": "Same bug already seen in your manual run (wandae -> 數量 0). 0 or any invented default = FAIL."
    }
  },
  {
    "id": "T04",
    "category": "product not in price list (looks similar to listed items)",
    "email": "Hello,\n\nDo you supply Platycerium sumbawense? We need 30 plants, medium, for a retail order next month.\n\nRegards,\nLisa Chen",
    "expected": {
      "route": "human_review",
      "reason": "product not found in price list",
      "品項": [
        {
          "名稱": "sumbawense",
          "尺寸": "M",
          "數量": 30
        }
      ],
      "note": "Lookup must fail cleanly — no fallback to a 'closest' Platycerium price."
    }
  },
  {
    "id": "T05",
    "category": "Chinese-English mixed + tier boundary (exactly 21 units)",
    "email": "Hi 老闆，\n\n我是在 LA 開植物店的，想跟你訂 Bacteria 小的 15 棵，另外 Jade Girl 中的也要 6 pcs。\nShipping 到 Los Angeles 大概多少？\n\nThanks!\nKevin 林",
    "expected": {
      "route": "auto_quote",
      "品項": [
        {
          "名稱": "Bacteria",
          "尺寸": "S",
          "數量": 15
        },
        {
          "名稱": "Jade Girl",
          "尺寸": "M",
          "數量": 6
        }
      ],
      "total_units": 21,
      "discount": 0.15,
      "unit_prices": {
        "Bacteria S": 20.4,
        "Jade Girl M": 25.5
      },
      "總計_USD": 459.0,
      "note": "小/中 -> S/M; 棵 and pcs -> plain integers. 21 is the first unit of the 15% tier (off-by-one check: no discount would give 540.00)."
    }
  },
  {
    "id": "T06",
    "category": "quantity in words + typo + size not stated (single-size item)",
    "email": "Hey,\n\nCould I get pricing on two dozen Konayki?\n\nThanks,\nJoe",
    "expected": {
      "route": "auto_quote",
      "品項": [
        {
          "名稱": "Konayuki",
          "尺寸": "M",
          "數量": 24
        }
      ],
      "total_units": 24,
      "discount": 0.15,
      "unit_prices": {
        "Konayuki M": 25.5
      },
      "總計_USD": 612.0,
      "acceptable_alternative": "human_review (typo not matched) is acceptable. Quantity 2 or 12, or a wrong product price = FAIL.",
      "note": "Konayuki only has size M in the list, so a missing size can be filled by the Code node (not by the LLM)."
    }
  },
  {
    "id": "T07",
    "category": "partial match — one item found, one not",
    "email": "Hi,\n\nPlease quote:\n1) Ridleyi MonkeyKing, large — 12 pcs\n2) Pink Lady variegated — 4 pcs\n\nThanks,\nAnna Müller\nPflanzenhaus Berlin",
    "expected": {
      "route": "human_review",
      "reason": "1 of 2 items not found in price list",
      "品項": [
        {
          "名稱": "Ridleyi MonkeyKing",
          "尺寸": "L",
          "數量": 12
        },
        {
          "名稱": "Pink Lady variegated",
          "尺寸": null,
          "數量": 4
        }
      ],
      "note": "Never send a partial quote. Whole email goes to review."
    }
  },
  {
    "id": "T08",
    "category": "quantity is a range / conditional",
    "email": "Hello,\n\nWe're considering around 30-50 Elsa depending on your price. If the price is good we might go bigger.\n\nBest,\nDavid",
    "expected": {
      "route": "human_review",
      "reason": "quantity ambiguous (range)",
      "品項": [
        {
          "名稱": "Elsa",
          "尺寸": null,
          "數量": null
        }
      ],
      "note": "LLM must not pick 30, 40 or 50. The range also crosses the 50/51 tier line."
    }
  },
  {
    "id": "T09",
    "category": "not a new inquiry (follow-up with quoted old thread)",
    "email": "Hi, any update on the tracking number for last week's order?\n\nThanks,\nRyan\n\n> On Oct 3, Ryan wrote:\n> We'd like 20 pcs of OMG medium and 10 Nano small.",
    "expected": {
      "route": "human_review",
      "reason": "no new quote request",
      "品項": [],
      "note": "Hallucination trap: product names only appear in the quoted old email. Quoting them again = FAIL."
    }
  },
  {
    "id": "T10",
    "category": "negation + look-alike names",
    "email": "Hi,\n\nWe still have plenty of Ridleyi Saman, so none of those this round. Just 25 Yellow Moon Dwarf please — the regular one, not the Totoro cross.\n\nThanks,\nSanne",
    "expected": {
      "route": "auto_quote",
      "品項": [
        {
          "名稱": "Yellow Moon Dwarf",
          "尺寸": "M",
          "數量": 25
        }
      ],
      "total_units": 25,
      "discount": 0.15,
      "unit_prices": {
        "Yellow Moon Dwarf M": 30.6
      },
      "總計_USD": 765.0,
      "note": "Ridleyi Saman must NOT appear. Must not match 'Yellow Moon Dwarf x Totoro' or 'Yellow moon'."
    }
  }
];

return tests.map(t => ({ json: t }));

